(() => {
  'use strict';
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const ui = { overlay:$('#overlay'), title:$('#overlayTitle'), copy:$('#overlayCopy'), start:$('#startButton'), status:$('#statusText'), health:$('#healthFill'), healthText:$('#healthText'), stamina:$('#staminaFill'), staminaText:$('#staminaText'), wave:$('#waveText'), caption:$('#waveCaption'), score:$('#scoreText'), kills:$('#killsText'), toast:$('#toast'), best:$('#bestScore'), sound:$('#soundButton') };
  const captions = ['THE FIRST CUT','BLOOD IN THE DUST','NO ROOM TO FALTER','THE LONG NIGHT','ASHES TO ASHES'];
  let W=innerWidth,H=innerHeight,dpr=1,last=0,scene='menu',wave=1,score=0,kills=0,best=Number(localStorage.getItem('bladebound-best')||0),enemies=[],particles=[],decor=[],keys={},pointer={x:W*.7,y:H*.5,down:false},touchDirs={},player=null,attackTimer=0,attackCooldown=0,dashCooldown=0,invuln=0,shake=0,toastTimer=0,roundDelay=0,audioOn=true,audioCtx=null;
  ui.best.textContent=String(best).padStart(4,'0');
  function resize(){W=innerWidth;H=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);makeDecor();}
  function makeDecor(){decor=[];const rand=(a,b)=>a+Math.random()*(b-a);for(let i=0;i<Math.max(28,Math.floor(W*H/17000));i++)decor.push({x:rand(20,W-20),y:rand(85,H-45),r:rand(1,3),a:rand(.06,.2)});}
  addEventListener('resize',resize);resize();
  function arena(){return {l:Math.max(24,W*.055),r:W-Math.max(24,W*.055),t:Math.max(84,H*.13),b:H-Math.max(100,H*.12)}}
  function begin(){scene='play';wave=1;score=0;kills=0;enemies=[];particles=[];player={x:W/2,y:H*.57,r:15,hp:100,max:100,face:0};attackTimer=attackCooldown=dashCooldown=invuln=0;roundDelay=0;ui.overlay.classList.add('hidden');ui.status.textContent='TRIAL IN PROGRESS';ui.caption.textContent=captions[0];updateHud();spawnWave();last=performance.now();}
  function spawnWave(){const count=wave+2;const a=arena();for(let i=0;i<count;i++){let side=i%4,x,y;if(side===0){x=a.l+30+Math.random()*(a.r-a.l-60);y=a.t-15}else if(side===1){x=a.r+15;y=a.t+30+Math.random()*(a.b-a.t-60)}else if(side===2){x=a.l+30+Math.random()*(a.r-a.l-60);y=a.b+15}else{x=a.l-15;y=a.t+30+Math.random()*(a.b-a.t-60)}let type=wave>=3&&Math.random()<.32?'brute':'raider';enemies.push({x,y,r:type==='brute'?18:13,hp:type==='brute'?3:1,max:type==='brute'?3:1,speed:(type==='brute'?48:62)+wave*4,damage:type==='brute'?17:11,type,hit:0,attack:Math.random()*.8,phase:Math.random()*6.2});}announce(`TRIAL ${String(wave).padStart(2,'0')} — ${count} FOES APPROACH`);}
  function updateHud(){const hp=Math.max(0,player?.hp??100);ui.health.style.width=`${hp}%`;ui.healthText.textContent=`${Math.ceil(hp)} / 100`;ui.stamina.style.width=`${Math.max(0,100-dashCooldown/2.1*100)}%`;ui.staminaText.textContent=dashCooldown<=0?'READY':'CHARGING';ui.wave.innerHTML=`${String(Math.min(wave,5)).padStart(2,'0')} <small>/ 05</small>`;ui.score.textContent=String(score).padStart(4,'0');ui.kills.textContent=kills;}
  function announce(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.8;}
  function startAttack(){if(scene!=='play'||attackCooldown>0)return;attackCooldown=.42;attackTimer=.22;let aimX=pointer.x-player.x,aimY=pointer.y-player.y;if(Math.hypot(aimX,aimY)<12&&enemies.length){const e=enemies.reduce((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)<Math.hypot(b.x-player.x,b.y-player.y)?a:b);aimX=e.x-player.x;aimY=e.y-player.y;}player.face=Math.atan2(aimY,aimX);sound('slash');}
  function dash(){if(scene!=='play'||dashCooldown>0)return;let dx=(keys.KeyD||touchDirs.right?1:0)-(keys.KeyA||touchDirs.left?1:0),dy=(keys.KeyS||touchDirs.down?1:0)-(keys.KeyW||touchDirs.up?1:0);if(!dx&&!dy){dx=Math.cos(player.face);dy=Math.sin(player.face);}const l=Math.hypot(dx,dy)||1;player.x+=dx/l*110;player.y+=dy/l*110;const a=arena();player.x=clamp(player.x,a.l+20,a.r-20);player.y=clamp(player.y,a.t+25,a.b-20);dashCooldown=2.1;invuln=.42;shake=3;for(let i=0;i<10;i++)particle(player.x,player.y,'#d7b575',1+Math.random()*2,Math.random()*Math.PI*2,50+Math.random()*80);sound('dash');}
  function clamp(n,a,b){return Math.max(a,Math.min(b,n));}
  function particle(x,y,color,r,angle,speed){particles.push({x,y,color,r,dx:Math.cos(angle)*speed,dy:Math.sin(angle)*speed,life:.35+Math.random()*.35,max:.7});}
  function sound(kind){if(!audioOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.type=kind==='slash'?'sawtooth':'triangle';o.frequency.setValueAtTime(kind==='slash'?260:180,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(kind==='slash'?90:90,audioCtx.currentTime+.12);g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.13);o.start();o.stop(audioCtx.currentTime+.14);}catch(_){}}
  function step(dt){if(scene!=='play')return;attackCooldown=Math.max(0,attackCooldown-dt);attackTimer=Math.max(0,attackTimer-dt);dashCooldown=Math.max(0,dashCooldown-dt);invuln=Math.max(0,invuln-dt);shake=Math.max(0,shake-dt*18);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');}
    let dx=(keys.KeyD||touchDirs.right?1:0)-(keys.KeyA||touchDirs.left?1:0),dy=(keys.KeyS||touchDirs.down?1:0)-(keys.KeyW||touchDirs.up?1:0),len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;player.x+=dx*190*dt;player.y+=dy*190*dt;}
    const a=arena();player.x=clamp(player.x,a.l+19,a.r-19);player.y=clamp(player.y,a.t+24,a.b-20);
    if(pointer.moved&&Math.hypot(pointer.x-player.x,pointer.y-player.y)>8)player.face=Math.atan2(pointer.y-player.y,pointer.x-player.x);
    if(attackTimer>0){for(const e of enemies){if(e.hit>0)continue;const ex=e.x-player.x,ey=e.y-player.y,d=Math.hypot(ex,ey),ang=Math.atan2(ey,ex),diff=Math.atan2(Math.sin(ang-player.face),Math.cos(ang-player.face));if(d<82+e.r&&Math.abs(diff)<.95){e.hp--;e.hit=.24;e.x+=Math.cos(player.face)*18;e.y+=Math.sin(player.face)*18;for(let i=0;i<7;i++)particle(e.x,e.y,e.type==='brute'?'#d18b65':'#c96e50',1+Math.random()*2,Math.random()*Math.PI*2,35+Math.random()*100);shake=2;sound('hit');if(e.hp<=0){score+=e.type==='brute'?180:100;kills++;for(let i=0;i<13;i++)particle(e.x,e.y,'#bd674d',1+Math.random()*3,Math.random()*Math.PI*2,45+Math.random()*140);}}}enemies=enemies.filter(e=>e.hp>0);}
    for(const e of enemies){e.hit=Math.max(0,e.hit-dt);e.attack-=dt;e.phase+=dt*3;const ex=player.x-e.x,ey=player.y-e.y,d=Math.hypot(ex,ey)||1;if(d>e.r+player.r+13){e.x+=ex/d*e.speed*dt;e.y+=ey/d*e.speed*dt;}else if(e.attack<=0&&invuln<=0){e.attack=e.type==='brute'?1.1:.82;player.hp-=e.damage;invuln=.55;shake=8;for(let i=0;i<8;i++)particle(player.x,player.y,'#d56d4f',2,Math.random()*Math.PI*2,55+Math.random()*100);sound('hurt');if(player.hp<=0){player.hp=0;finish(false);}}
      e.x=clamp(e.x,a.l+10,a.r-10);e.y=clamp(e.y,a.t+14,a.b-10);
    }
    particles=particles.filter(p=>{p.life-=dt;p.x+=p.dx*dt;p.y+=p.dy*dt;p.dx*=.97;p.dy*=.97;return p.life>0;});
    if(!enemies.length){roundDelay+=dt;if(roundDelay===dt)announce(wave===5?'THE YARD IS YOURS':'TRIAL CLEARED');if(roundDelay>1.5){roundDelay=0;if(wave>=5)finish(true);else{wave++;ui.caption.textContent=captions[wave-1];player.hp=Math.min(100,player.hp+15);spawnWave();}}}else roundDelay=0;
    updateHud();
  }
  function finish(win){scene=win?'won':'dead';ui.status.textContent=win?'YARD CONQUERED':'FALLEN IN THE YARD';if(score>best){best=score;localStorage.setItem('bladebound-best',best);ui.best.textContent=String(best).padStart(4,'0');}ui.title.innerHTML=win?'YARD<br><span>CONQUERED</span>':'YOU HAVE<br><span>FALLEN</span>';ui.copy.textContent=win?`The Ashen Yard remembers your name. You earned ${score} honor.`:`You felled ${kills} foes and earned ${score} honor. The yard is never done.`;ui.start.innerHTML='<span>FIGHT AGAIN</span><b>→</b>';ui.overlay.classList.remove('hidden');}
  function draw(){ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);ctx.clearRect(-10,-10,W+20,H+20);const grd=ctx.createLinearGradient(0,0,W,H);grd.addColorStop(0,'#28302c');grd.addColorStop(.52,'#202724');grd.addColorStop(1,'#171e1d');ctx.fillStyle=grd;ctx.fillRect(0,0,W,H);const a=arena();
    // worn flagstones
    const tile=64;for(let y=a.t;y<a.b;y+=tile){for(let x=a.l;x<a.r;x+=tile){const n=((Math.floor(x/tile)*13+Math.floor(y/tile)*7)%5);ctx.fillStyle=['#303632','#2c332f','#333833','#29312e','#303733'][n];ctx.fillRect(x+1,y+1,tile-2,tile-2);ctx.strokeStyle='rgba(12,16,15,.3)';ctx.lineWidth=1;ctx.strokeRect(x+1,y+1,tile-2,tile-2);}}
    ctx.save();ctx.beginPath();ctx.rect(a.l,a.t,a.r-a.l,a.b-a.t);ctx.clip();for(const d of decor){ctx.fillStyle=`rgba(190,172,129,${d.a})`;ctx.beginPath();ctx.ellipse(d.x,d.y,d.r*1.6,d.r,Math.random()*.4,0,Math.PI*2);ctx.fill();}ctx.restore();
    // arena boundary and iron corner stakes
    ctx.strokeStyle='rgba(205,176,122,.35)';ctx.lineWidth=2;ctx.strokeRect(a.l,a.t,a.r-a.l,a.b-a.t);ctx.strokeStyle='rgba(9,13,12,.55)';ctx.lineWidth=8;ctx.strokeRect(a.l-4,a.t-4,a.r-a.l+8,a.b-a.t+8);ctx.strokeStyle='rgba(205,176,122,.35)';ctx.lineWidth=1;ctx.strokeRect(a.l,a.t,a.r-a.l,a.b-a.t);
    for(const [x,y] of [[a.l,a.t],[a.r,a.t],[a.l,a.b],[a.r,a.b]]){ctx.fillStyle='#b98557';ctx.shadowColor='#d3774e';ctx.shadowBlur=14;ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;}
    // soft ambient light around fighter
    if(player){const light=ctx.createRadialGradient(player.x,player.y,20,player.x,player.y,Math.max(W,H)*.48);light.addColorStop(0,'rgba(221,170,112,.07)');light.addColorStop(1,'rgba(0,0,0,.40)');ctx.fillStyle=light;ctx.fillRect(0,0,W,H);}
    for(const e of enemies)drawEnemy(e);if(player)drawPlayer();for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r*Math.min(1,p.life*4),0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
    // subtle edge vignette
    const v=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.28,W/2,H/2,Math.max(W,H)*.76);v.addColorStop(0,'transparent');v.addColorStop(1,'rgba(4,8,8,.52)');ctx.fillStyle=v;ctx.fillRect(0,0,W,H);ctx.restore();
  }
  function drawPlayer(){const p=player;ctx.save();ctx.translate(p.x,p.y);ctx.globalAlpha=p.invuln>0?0.55+Math.sin(performance.now()*.035)*.3:1;
    // shadow and cloak
    ctx.fillStyle='rgba(0,0,0,.35)';ctx.beginPath();ctx.ellipse(2,11,18,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#784c3c';ctx.beginPath();ctx.moveTo(-12,-7);ctx.lineTo(13,-6);ctx.lineTo(15,9);ctx.lineTo(0,17);ctx.lineTo(-15,8);ctx.closePath();ctx.fill();ctx.fillStyle='#b57958';ctx.beginPath();ctx.arc(0,-7,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#26302e';ctx.beginPath();ctx.arc(0,-9,10,Math.PI,Math.PI*2);ctx.lineTo(10,-5);ctx.lineTo(-9,-5);ctx.fill();ctx.fillStyle='#e2c89b';ctx.beginPath();ctx.arc(4,-7,1.5,0,Math.PI*2);ctx.fill();
    // sword sweep
    ctx.rotate(p.face);if(attackTimer>0){const progress=1-attackTimer/.22;ctx.strokeStyle=`rgba(238,207,146,${.72-progress*.45})`;ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,47,-.92+progress*-.35,.92+progress*.45);ctx.stroke();ctx.strokeStyle='rgba(226,133,91,.38)';ctx.lineWidth=9;ctx.beginPath();ctx.arc(0,0,47,-.82+progress*-.3,.82+progress*.4);ctx.stroke();}
    ctx.rotate(.25);ctx.fillStyle='#49372b';ctx.fillRect(9,-3,9,6);ctx.fillStyle='#c9a564';ctx.fillRect(14,-2,3,4);ctx.beginPath();ctx.moveTo(17,-2);ctx.lineTo(43,-1);ctx.lineTo(48,0);ctx.lineTo(43,1);ctx.lineTo(17,2);ctx.closePath();ctx.fillStyle='#d9d5c7';ctx.fill();ctx.strokeStyle='#fff0cc';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(20,0);ctx.lineTo(44,0);ctx.stroke();ctx.restore();ctx.globalAlpha=1;}
  function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y+Math.sin(e.phase)*1.4);ctx.fillStyle='rgba(0,0,0,.34)';ctx.beginPath();ctx.ellipse(1,10,e.r*1.2,e.r*.55,0,0,Math.PI*2);ctx.fill();const hurt=e.hit>0;ctx.fillStyle=hurt?'#f0c39b':e.type==='brute'?'#8f5945':'#9b614b';ctx.beginPath();ctx.arc(0,0,e.r,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.type==='brute'?'#473c35':'#353b35';ctx.beginPath();ctx.arc(0,-4,e.r*.78,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#e6b781';ctx.fillRect(-6,-2,3,2);ctx.fillRect(4,-2,3,2);if(e.type==='brute'){ctx.strokeStyle='#c28a60';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-10,-11);ctx.lineTo(-14,-18);ctx.moveTo(10,-11);ctx.lineTo(14,-18);ctx.stroke();}if(e.hp<e.max){ctx.fillStyle='#141817';ctx.fillRect(-e.r,-e.r-9,e.r*2,3);ctx.fillStyle='#dc7958';ctx.fillRect(-e.r,-e.r-9,e.r*2*e.hp/e.max,3);}ctx.restore();}
  function frame(t){const dt=Math.min(.033,(t-last)/1000||0);last=t;step(dt);draw();requestAnimationFrame(frame);}requestAnimationFrame(frame);
  ui.start.addEventListener('click',()=>{ui.start.innerHTML='<span>ENTER THE YARD</span><b>→</b>';begin();});
  addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.code==='Space')dash();if((e.code==='Enter'||e.code==='KeyR')&&scene!=='play')begin();});addEventListener('keyup',e=>keys[e.code]=false);
  canvas.addEventListener('pointermove',e=>{pointer.x=e.clientX;pointer.y=e.clientY;pointer.moved=true;});canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){pointer.x=e.clientX;pointer.y=e.clientY;pointer.down=true;startAttack();}});addEventListener('pointerup',()=>pointer.down=false);
  document.querySelectorAll('[data-dir]').forEach(btn=>{const dir=btn.dataset.dir;btn.addEventListener('pointerdown',e=>{e.preventDefault();touchDirs[dir]=true;btn.setPointerCapture(e.pointerId);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])btn.addEventListener(ev,()=>touchDirs[dir]=false);});
  $('#mobileAttack').addEventListener('pointerdown',e=>{e.preventDefault();pointer.moved=false;startAttack();});$('#mobileDash').addEventListener('pointerdown',e=>{e.preventDefault();dash();});
  ui.sound.addEventListener('click',()=>{audioOn=!audioOn;ui.sound.innerHTML=`♪ <span>SOUND ${audioOn?'ON':'OFF'}</span>`;});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)last=performance.now();});
})();

